using Godot;
using Godot.Collections;

public partial class HexTileInfo : Control
{
    [Signal] public delegate void action_requestedEventHandler(string action_id, Vector2I coord);
    private TextureRect? frame,core; private Label? title,terrain; private VBoxContainer? actions; private Tween? tween; private Vector2I coord=new(-9999,-9999);
    public override void _Ready(){AddToGroup("hex_tile_info");AddToGroup("map_overlay_blocker");Hide();frame=GetNodeOrNull<TextureRect>("%ScrollFrame");core=GetNodeOrNull<TextureRect>("%ScrollCore");title=GetNodeOrNull<Label>("%TitleLabel");terrain=GetNodeOrNull<Label>("%TerrainLabel");actions=GetNodeOrNull<VBoxContainer>("%ActionList");if(core is not null){core.PivotOffset=new(core.Size.X/2,0);core.Scale=new(1,0);}if(frame is not null)frame.GuiInput+=on_frame_click;rebuild_actions([]);}
    public Rect2 get_ui_rect()=>frame?.GetGlobalRect()??core?.GetGlobalRect()??GetGlobalRect();
    public void show_world_site_info(Vector2I p_coord,string name,Array<string> lines,Array<Dictionary> buttons){coord=p_coord;if(title is not null)title.Text=name;if(terrain is not null)terrain.Text=string.Join("\n",lines);rebuild_actions(buttons);unfurl();}
    public void show_cell_info(GodotObject map,Vector2I cell){if(map is null||!map.Call("has_cell",cell).AsBool()&&!map.Get("cells").AsGodotDictionary().ContainsKey(cell))return;coord=new(-9999,-9999);if(title is not null)title.Text="地块信息";rebuild_actions([]);var world=map.Call("get_world_cell",cell).AsGodotObject();if(GodotObject.IsInstanceValid(world)){var parts=new List<string>();var name=world!.Get("name").AsString();parts.Add(string.IsNullOrEmpty(name)?"地形："+map.Call("get_display_terrain_name",cell).AsString():"地块："+name);var description=world.Get("description").AsString();if(!string.IsNullOrEmpty(description))parts.Add(description);var resource=world.Get("resource_type").AsString();if(!string.IsNullOrEmpty(resource)&&world.Get("resource_amount").AsInt32()>0)parts.Add($"资源：{WorldMapData.get_resource_display_name(resource)} x{world.Get("resource_amount").AsInt32()}");foreach(var road in map.Call("get_world_road_summary",cell).AsGodotArray())parts.Add(road.AsString());if(terrain is not null)terrain.Text=string.Join("\n",parts);unfurl();return;}if(terrain is not null)terrain.Text="地形："+map.Call("get_display_terrain_name",cell).AsString();unfurl();}
    private void rebuild_actions(Array<Dictionary> items){if(actions is null)return;foreach(var child in actions.GetChildren())child.QueueFree();foreach(var item in items){var id=item.TryGetValue("id",out var idValue)?idValue.AsString():"";var button=new Button{Text=item.TryGetValue("label",out var labelValue)?labelValue.AsString():"未命名操作",Disabled=item.TryGetValue("enabled",out var enabled)&&!enabled.AsBool(),CustomMinimumSize=new(0,36)};button.Pressed+=()=>EmitSignal(SignalName.action_requested,id,coord);actions.AddChild(button);if(item.TryGetValue("detail",out var detail)&&!string.IsNullOrEmpty(detail.AsString()))actions.AddChild(new Label{Text=detail.AsString(),AutowrapMode=TextServer.AutowrapMode.WordSmart});}actions.Visible=items.Count>0;}
    private void on_frame_click(InputEvent input){if(input is InputEventMouseButton {Pressed:true})roll_up();}
    private void unfurl(){Show();MoveToFront();tween?.Kill();if(core is null)return;core.Scale=new(1,0);tween=CreateTween();tween.TweenProperty(core,"scale",Vector2.One,.35f*Engine.TimeScale);}
    private void roll_up(){tween?.Kill();if(core is null){Hide();return;}tween=CreateTween();tween.TweenProperty(core,"scale",new Vector2(1,0),.28f*Engine.TimeScale);tween.Finished+=Hide;}
}
